from openpyxl import load_workbook
path='/root/output/result.xlsx'
wb=load_workbook(path, data_only=False)
ws=wb['Task']
check_cells=['H12','L17','H35','L40','H42','H46','H47','H50','L50']
print('Validation formulas from', path)
errors=[]
for addr in check_cells:
    val=ws[addr].value
    print(f'{addr}: {val}')
    if val is None or val == '':
        errors.append(f'{addr} is empty')
for addr in ['H46','H47']:
    val=ws[addr].value or ''
    if 'PERCENTILE.INC' in val:
        errors.append(f'{addr} uses PERCENTILE.INC')
    if 'PERCENTILE(' not in val:
        errors.append(f'{addr} does not use legacy PERCENTILE')
# broader blank/formula validation for all written ranges
for row_start,row_end in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(row_start,row_end+1):
        for c in range(8,13):
            addr=ws.cell(r,c).coordinate
            val=ws.cell(r,c).value
            if val is None or val == '' or not (isinstance(val,str) and val.startswith('=')):
                errors.append(f'{addr} missing formula: {val!r}')
            if isinstance(val,str) and 'PERCENTILE.INC' in val:
                errors.append(f'{addr} contains PERCENTILE.INC')
if errors:
    print('VALIDATION FAILED')
    for e in errors:
        print('  -', e)
    raise SystemExit(1)
print('VALIDATION PASSED: all checked formulas are present; percentile formulas use legacy PERCENTILE only.')
